mapper.select:
SELECT 
FROM sys_job_api_idempotency
WHERE tenant_id = #{tenantId}
  AND token_id = #{tokenId}
  AND job_config_id = #{jobConfigId}
  AND idempotency_key_hash = #{keyHash}
  AND expires_at > #{now}
  AND del_flag = 0
LIMIT 1

mapper.update:
UPDATE sys_job_api_idempotency
SET del_flag = 1,
    update_time = NOW()
WHERE tenant_id = #{tenantId}
  AND token_id = #{tokenId}
  AND job_config_id = #{jobConfigId}
  AND idempotency_key_hash = #{keyHash}
  AND expires_at <= #{now}
  AND del_flag = 0
